import ArgumentParser
import RemindersCore

/// Shells `reminders completions` supports. Anything else is a usage error (exit 64).
enum CompletionShellKind: String, CaseIterable, ExpressibleByArgument {
  case bash, zsh, fish

  var argumentParserShell: CompletionShell {
    switch self {
    case .bash: .bash
    case .zsh: .zsh
    case .fish: .fish
    }
  }
}

/// Shell completion scripts for every visible command, flag and option, generated by ArgumentParser from the
/// command tree. ArgumentParser leaves out command aliases, so they are added here: an alias completes as a command
/// name and then exactly like the command it stands for.
enum CompletionScript {
  struct Alias: Equatable {
    var name: String
    var command: String
    var abstract: String
  }

  static var aliases: [Alias] {
    RemindersCommand.configuration.subcommands.flatMap { command in
      let configuration = command.configuration
      return configuration.aliases.map {
        Alias(name: $0, command: configuration.commandName ?? "", abstract: configuration.abstract)
      }
    }
  }

  static func generate(for shell: CompletionShellKind) -> String {
    let script = RemindersCommand.completionScript(for: shell.argumentParserShell)
    let patched =
      switch shell {
      case .bash: bash(script)
      case .zsh: zsh(script)
      case .fish: fish(script)
      }
    return patched.hasSuffix("\n") ? patched : patched + "\n"
  }

  private static let root = ProductInfo.name

  private static func bash(_ script: String) -> String {
    var lines: [String] = []
    for line in script.split(separator: "\n", omittingEmptySubsequences: false).map(String.init) {
      if line.contains("COMPREPLY+=($(compgen -W '"), line.contains(" help' -- ") {
        lines.append(line.replacing(" help' -- ", with: " help \(aliases.map(\.name).joined(separator: " "))' -- "))
        continue
      }
      if line.hasPrefix("    today|") {
        lines += aliases.map { "    '\($0.name)') _\(root)_\($0.command) ;;" }
      }
      lines.append(line)
    }
    return lines.joined(separator: "\n")
  }

  private static func zsh(_ script: String) -> String {
    var lines: [String] = []
    for line in script.split(separator: "\n", omittingEmptySubsequences: false).map(String.init) {
      if line.trimmingPrefix(while: \.isWhitespace).hasPrefix("compdef ") {
        // `source <(reminders completions zsh)` before `compinit` has run must not fail on a missing `compdef`.
        let indent = line.prefix(while: \.isWhitespace)
        lines.append("\(indent)if (( $+functions[compdef] )); then \(line.trimmingPrefix(while: \.isWhitespace)); fi")
        continue
      }
      if line.hasPrefix("        today|") {
        lines += aliases.map { "        '\($0.name)') _\(root)_\($0.command) && ret=0 ;;" }
      }
      lines.append(line)
      for alias in aliases where line == "            '\(alias.command):\(alias.abstract)'" {
        lines.append("            '\(alias.name):\(alias.abstract)'")
      }
    }
    return lines.joined(separator: "\n")
  }

  private static func fish(_ script: String) -> String {
    var lines: [String] = []
    for line in script.split(separator: "\n", omittingEmptySubsequences: false).map(String.init) {
      lines.append(line)
      for alias in aliases {
        if line == "        case '\(alias.command)'" {
          lines[lines.count - 1] += " '\(alias.name)'"
        } else if line.contains("\"\(root) \(alias.command)\"") {
          lines.append(line.replacing("\"\(root) \(alias.command)\"", with: "\"\(root) \(alias.name)\""))
        } else if line.contains("-fa '\(alias.command)' -d ") {
          lines.append(line.replacing("-fa '\(alias.command)' -d ", with: "-fa '\(alias.name)' -d "))
        }
      }
    }
    return lines.joined(separator: "\n")
  }
}
